insert into menu_items(menu_key,title,path,sort_order,permission,children,is_active,parent_id)
select c.menu_key,c.title,c.path,c.sort_order,null,'[]'::jsonb,true,p.id
from child_seed c join menu_items p on p.menu_key=c.parent_key
on conflict(menu_key) where menu_key is not null do update
set title=excluded.title,path=excluded.path,sort_order=excluded.sort_order,parent_id=excluded.parent_id,is_active=true,updated_at=now();

insert into menu_item_panels(menu_item_id,panel_code,is_shared,sort_order,is_visible)
select c.id,p.code,true,c.sort_order,true
from menu_items c cross join menu_panels p
where c.menu_key like '01-dashboard:%' or c.menu_key like '02-organizations:%' or c.menu_key like '03-users-access:%' or c.menu_key like '04-customers-360:%'
or c.menu_key like '05-smart-calendar:%' or c.menu_key like '06-business-rules:%' or c.menu_key like '07-sla:%' or c.menu_key like '08-accounting-finance:%'
or c.menu_key like '09-commerce-stores:%' or c.menu_key like '10-domains:%' or c.menu_key like '11-merchants:%' or c.menu_key like '12-sellers:%'
or c.menu_key like '13-payments-settlement:%' or c.menu_key like '14-form-builder:%' or c.menu_key like '15-menu-builder:%' or c.menu_key like '16-page-builder:%'
or c.menu_key like '17-frontend-management:%' or c.menu_key like '18-notifications:%' or c.menu_key like '19-documents-governance:%' or c.menu_key like '20-system-settings:%'
or c.menu_key like '21-purchasing-supply:%' or c.menu_key like '22-sales-revenue:%' or c.menu_key like '23-inventory-warehouse:%' or c.menu_key like '24-production:%'
or c.menu_key like '25-costing:%' or c.menu_key like '26-treasury-bank:%' or c.menu_key like '27-receivables:%' or c.menu_key like '28-payables:%'
or c.menu_key like '29-wallet-ledger:%' or c.menu_key like '30-projects-cost-centers:%' or c.menu_key like '31-fixed-assets:%' or c.menu_key like '32-tax-e-invoicing:%'
or c.menu_key like '33-budget-financial-control:%' or c.menu_key like '34-financial-commitments:%' or c.menu_key like '35-credit-financing:%' or c.menu_key like '36-loans:%'
or c.menu_key like '37-collateral-guarantees:%' or c.menu_key like '38-collections:%' or c.menu_key like '39-human-resources:%' or c.menu_key like '40-ai-finance:%'
or c.menu_key like '41-ai-documents-ocr:%' or c.menu_key like '42-audit-internal-control:%' or c.menu_key like '43-communication-hub:%' or c.menu_key like '44-marketing-content:%'
or c.menu_key like '45-search-analytics:%' or c.menu_key like '46-unified-applications:%' or c.menu_key like '47-contracts-legal:%' or c.menu_key like '48-shipping-delivery:%'
or c.menu_key like '49-reconciliation:%' or c.menu_key like '50-release-health:%'
on conflict(menu_item_id,panel_code) do update set is_shared=true,is_visible=true,sort_order=excluded.sort_order;
commit;
